//! Conversion between the Unicode and ASCII Compatible Encoding forms.

use super::transform::to_lower;
use super::ACE_PREFIX;

/// Mirrors `idna::to_ascii()`: `"xn--" + to_lower(s)`.
///
/// The prefix is added unconditionally — the C++ routine never checks whether
/// the input is already ASCII or already prefixed, so `to_ascii("xn--a")`
/// yields `"xn--xn--a"`.
pub fn to_ascii(input: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(ACE_PREFIX.len() + input.len());
    out.extend_from_slice(ACE_PREFIX);
    out.extend_from_slice(&to_lower(input));
    out
}

/// Mirrors `idna::punycode_encode()`: `"xn--" + s`.
///
/// Same as [`to_ascii`] but without the case fold.
pub fn punycode_encode(input: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(ACE_PREFIX.len() + input.len());
    out.extend_from_slice(ACE_PREFIX);
    out.extend_from_slice(input);
    out
}

/// Mirrors `idna::to_unicode()`: `s.find("xn--") == 0 ? s.substr(4) : s`.
///
/// The comparison is case-sensitive, so an upper-case `"XN--"` is left alone.
pub fn to_unicode(input: &[u8]) -> Vec<u8> {
    strip_ace_prefix(input).to_vec()
}

/// Mirrors `idna::punycode_decode()`, which is byte-identical to `to_unicode()`.
pub fn punycode_decode(input: &[u8]) -> Vec<u8> {
    strip_ace_prefix(input).to_vec()
}

/// Drops a leading `"xn--"`, leaving anything else untouched.
fn strip_ace_prefix(input: &[u8]) -> &[u8] {
    match input.strip_prefix(ACE_PREFIX) {
        Some(rest) => rest,
        None => input,
    }
}
