}
sub encs { return join('', map { enc($_) } @_) }

# ---------------------------------------------------------------- runner
# returns (exitcode, signal)
sub run_to {
    my ($file, $prog, @args) = @_;
    my $pid = fork();
    die "fork: $!" unless defined $pid;
    if ($pid == 0) {
        open(STDOUT, '>', $file)      or POSIX::_exit(127);
        open(STDERR, '>', "$file.err") or POSIX::_exit(127);
        { exec { $prog } ($prog, @args); }
        POSIX::_exit(127);
    }
    waitpid($pid, 0);
    my $st = $?;
    return ($st >> 8, $st & 127);
}

sub same_files {
    my $r = system('cmp', '-s', $FA, $FB);
    return $r == 0 ? 1 : 0;
}

sub slurp {
    my ($f) = @_;
    open(my $fh, '<', $f) or return '';
    binmode($fh);
