        elsif ($b == 0x27) { $o .= "\\'" }
        elsif ($b == 0x0A) { $o .= '\\n' }
        elsif ($b == 0x0D) { $o .= '\\r' }
        elsif ($b == 0x09) { $o .= '\\t' }
