# ---------------------------------------------------------------- utf8 encoder
sub enc {
    my ($cp) = @_;
    if    ($cp < 0x80)    { return chr($cp) }
    elsif ($cp < 0x800)   { return chr(0xC0 | ($cp >> 6)) . chr(0x80 | ($cp & 0x3F)) }
    elsif ($cp < 0x10000) { return chr(0xE0 | ($cp >> 12)) . chr(0x80 | (($cp >> 6) & 0x3F)) . chr(0x80 | ($cp & 0x3F)) }
