#!/usr/bin/perl
# Round 2: locale sensitivity, exhaustive 2-byte space, random high-byte fuzz,
# long inputs, many-argv.
use strict;
use warnings;
use POSIX ();

my $CPP  = '/workspace/dataset/test11_executable';
my $RUST = '/output/test11';
my $DIR  = '/tmp/wf-fuzz-r1-4/run2';
mkdir $DIR;
my $FA = "$DIR/a.out";
my $FB = "$DIR/b.out";

my %ENVOVR;   # extra env applied to both children

sub run_to {
    my ($file, $prog, @args) = @_;
    my $pid = fork();
    die "fork: $!" unless defined $pid;
    if ($pid == 0) {
        open(STDOUT, '>', $file)       or POSIX::_exit(127);
        open(STDERR, '>', "$file.err") or POSIX::_exit(127);
        for my $k (keys %ENVOVR) { $ENV{$k} = $ENVOVR{$k} }
        { no warnings; exec { $prog } ($prog, @args); }
        POSIX::_exit(127);
    }
    waitpid($pid, 0);
    my $st = $?;
    return ($st >> 8, $st & 127);
}
sub same_files { return system('cmp', '-s', $FA, $FB) == 0 ? 1 : 0 }
sub slurp { my ($f) = @_; open(my $fh, '<', $f) or return ''; binmode($fh); local $/; my $d = <$fh>; close $fh; return defined($d) ? $d : '' }
sub pretty {
    my ($s) = @_; my $o = '';
    for my $c (split //, $s) { my $b = ord($c);
        if ($b == 0x5C) { $o .= '\\\\' } elsif ($b == 0x27) { $o .= "\\'" }
        elsif ($b == 0x0A) { $o .= '\\n' } elsif ($b == 0x0D) { $o .= '\\r' } elsif ($b == 0x09) { $o .= '\\t' }
        elsif ($b >= 0x20 && $b < 0x7F) { $o .= $c } else { $o .= sprintf('\\x%02x', $b) } }
    return $o;
}
sub ansi_c {
    my ($s) = @_; my $o = '';
    for my $c (split //, $s) { my $b = ord($c);
        if ($b == 0x5C) { $o .= '\\\\' } elsif ($b == 0x27) { $o .= "\\'" }
        elsif ($b >= 0x20 && $b < 0x7F) { $o .= $c } else { $o .= sprintf('\\x%02x', $b) } }
    return "\$'" . $o . "'";
}
sub repro_cmd {
    my (@args) = @_;
    my $pre = join('', map { "$_=" . ansi_c($ENVOVR{$_}) . ' ' } sort keys %ENVOVR);
    my $q = join(' ', map { ansi_c($_) } @args);
    return "args=($q); ${pre}/workspace/dataset/test11_executable \"\${args[\@]}\" > /tmp/a.out; ${pre}/output/test11 \"\${args[\@]}\" > /tmp/b.out; cmp /tmp/a.out /tmp/b.out";
}

my ($total, $bad) = (0, 0);
sub check {
    my ($name, @args) = @_;
    $total++;
    my ($ca, $sa) = run_to($FA, $CPP,  @args);
    my ($cb, $sb) = run_to($FB, $RUST, @args);
    my $eq = same_files();
    return if $eq && $ca == $cb && $sa == $sb;
    my $confirmed = 1;
    for my $i (1 .. 2) {
        my ($xa, $ya) = run_to($FA, $CPP,  @args);
        my ($xb, $yb) = run_to($FB, $RUST, @args);
        $confirmed = 0 unless (same_files() == $eq && $xa == $ca && $xb == $cb && $ya == $sa && $yb == $sb);
    }
    $bad++;
    my $oa = slurp($FA); my $ob = slurp($FB);
    print "=== MISMATCH $name (confirmed=$confirmed)\n";
    print "  env=[", join(' ', map { "$_=$ENVOVR{$_}" } sort keys %ENVOVR), "]\n";
    print "  argc=", scalar(@args), " args=[", join(', ', map { "'" . pretty(substr($_,0,120)) . "'" } @args), "]\n";
    print "  exit: cpp=$ca sig=$sa | rust=$cb sig=$sb\n";
    print "  cpp  len=", length($oa), " : '", pretty(substr($oa, 0, 300)), "'\n";
    print "  rust len=", length($ob), " : '", pretty(substr($ob, 0, 300)), "'\n";
    print "  repro: ", repro_cmd(@args), "\n";
}

# ------------------------------------------------- A. locale sensitivity
# If the C++ lib called setlocale(LC_ALL,""), ::tolower on high bytes would
# change under an 8-bit locale while Rust's to_ascii_lowercase would not.
my @LOCALES = ('C', 'POSIX', 'C.UTF-8', 'en_US.UTF-8', 'en_US.ISO-8859-1',
               'de_DE.ISO-8859-1', 'tr_TR.ISO-8859-9', 'tr_TR.UTF-8',
               'ru_RU.KOI8-R', 'ru_RU.UTF-8', 'ja_JP.EUC-JP', 'zh_CN.GB18030',
               'lt_LT.ISO-8859-13', 'el_GR.ISO-8859-7', 'invalid_LOCALE.XYZ');
my @LOCALE_INPUTS = (
    (map { chr($_) } 0xC0, 0xC3, 0xC9, 0xD0, 0xDE, 0xDF, 0xE0, 0xFF, 0x80, 0xB5, 0x9F, 0xAA, 0xB2),
    join('', map { chr($_) } 0x80 .. 0xFF),
    'ABCXYZ', 'AbCdEf.GhI', 'I' . chr(0xDD) . 'i',
    chr(0xC3) . chr(0xA9), chr(0xC3) . chr(0x89),
    chr(0xD0) . chr(0x9F) . chr(0xD0) . chr(0xA0),
    'xn--' . chr(0xC0), 'XN--' . chr(0xC0),
);
for my $loc (@LOCALES) {
    for my $var ('LC_ALL', 'LC_CTYPE', 'LANG') {
        %ENVOVR = ($var => $loc);
        for my $in (@LOCALE_INPUTS) {
            check("locale-$var=$loc", $in);
        }
    }
}
%ENVOVR = ();

# ------------------------------------------------- B. exhaustive 2-byte space
# every ordered pair of bytes 0x01..0xFF where at least one byte is >= 0x80
for my $a (1 .. 255) {
    for my $b (1 .. 255) {
        next unless ($a >= 0x80 || $b >= 0x80);
        check(sprintf('exh2-%02x%02x', $a, $b), chr($a) . chr($b));
    }
}

print "PHASE-B done total=$total bad=$bad\n";

# ------------------------------------------------- C. random high-byte fuzz
srand(20260808);
for my $i (1 .. 3000) {
    my $len = 1 + int(rand(80));
    my $mode = $i % 5;
    my $s = '';
    for my $j (1 .. $len) {
        my $b;
        if    ($mode == 0) { $b = 0x80 + int(rand(128)) }                # pure high
        elsif ($mode == 1) { $b = 1 + int(rand(255)) }                   # any
        elsif ($mode == 2) { $b = (rand() < 0.5) ? (0x80 + int(rand(128))) : (0x41 + int(rand(26))) }
        elsif ($mode == 3) { $b = (rand() < 0.3) ? 0x2E : (0x80 + int(rand(128))) }  # dots + high
        else               { $b = (rand() < 0.5) ? (0xC0 + int(rand(64))) : (0x80 + int(rand(64))) } # lead/cont soup
        $s .= chr($b);
    }
    $s = 'xn--' . $s if $i % 7 == 0;
    $s = 'XN--' . $s if $i % 11 == 0;
    check("rand-$i", $s);
}

# random *valid* UTF-8 strings across all planes
for my $i (1 .. 1500) {
    my $n = 1 + int(rand(30));
    my $s = '';
    for my $j (1 .. $n) {
        my $cp;
        my $r = rand();
        if    ($r < 0.15) { $cp = 0x20 + int(rand(0x5F)) }
        elsif ($r < 0.35) { $cp = 0x80 + int(rand(0x780)) }
        elsif ($r < 0.60) { $cp = 0x800 + int(rand(0xD800 - 0x800)) }
        elsif ($r < 0.75) { $cp = 0xE000 + int(rand(0x10000 - 0xE000)) }
        else              { $cp = 0x10000 + int(rand(0x100000)) }
        if    ($cp < 0x80)    { $s .= chr($cp) }
        elsif ($cp < 0x800)   { $s .= chr(0xC0 | ($cp >> 6)) . chr(0x80 | ($cp & 0x3F)) }
        elsif ($cp < 0x10000) { $s .= chr(0xE0 | ($cp >> 12)) . chr(0x80 | (($cp >> 6) & 0x3F)) . chr(0x80 | ($cp & 0x3F)) }
        else { $s .= chr(0xF0 | ($cp >> 18)) . chr(0x80 | (($cp >> 12) & 0x3F)) . chr(0x80 | (($cp >> 6) & 0x3F)) . chr(0x80 | ($cp & 0x3F)) }
    }
    check("randu-$i", $s);
}

print "PHASE-C done total=$total bad=$bad\n";

# ------------------------------------------------- D. dense length sweep
for my $n (0 .. 300) {
    check("dlen-ff-$n",  chr(0xFF) x $n) if $n > 0;
    check("dlen-c3-$n",  substr((chr(0xC3) . chr(0xA9)) x ($n + 1), 0, $n)) if $n > 0;
}
for my $n (60 .. 68, 250 .. 260) {
    check("dlen-em-$n", substr(chr(0xF0).chr(0x9F).chr(0x98).chr(0x80) x 100, 0, $n));
    check("dlen-mix-$n", substr(('a' . chr(0xFF) . '.') x 200, 0, $n));
}
# large inputs
for my $n (1000, 4095, 4096, 8191, 8192, 65535, 65536, 131071, 131072) {
    check("big-ff-$n",  chr(0xFF) x $n);
    check("big-cjk-$n", substr((chr(0xE4).chr(0xB8).chr(0xAD)) x (int($n/3)+2), 0, $n));
    check("big-dot-$n", substr((chr(0xFF) . '.') x $n, 0, $n));
}

print "PHASE-D done total=$total bad=$bad\n";

# ------------------------------------------------- E. many argv elements
for my $k (1, 2, 10, 100, 1000, 5000) {
    check("nargs-ff-$k",  map { chr(0xFF) x ($_ % 5 + 1) } 1 .. $k);
    check("nargs-mix-$k", map { ($_ % 3 == 0) ? '' : (chr(0xC3).chr(0xA9)) x ($_ % 4 + 1) } 1 .. $k);
}
# all-empty argv sets
for my $k (1 .. 20) { check("nargs-empty-$k", map { '' } 1 .. $k) }

print "TOTAL CASES EXECUTED: $total\n";
print "TOTAL MISMATCHES: $bad\n";
